argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge';$app=Join-Path $root 'app';$data=Join-Path $app 'data'
$backup='E:\WebAIBridge-R65-SAFETY-BACKUP-20261014-GPT6-I1'
if(Test-Path -LiteralPath $backup){throw 'REFUSE_EXISTING_BACKUP'}
$head=[string](& git.exe -C $root rev-parse HEAD)
if($head.Trim() -ne '66e2ca7681b5e4c4affde9641b69e5582b718f99'){throw 'REFUSE_HEAD_CHANGED'}
if(@(& git.exe -C $root status --porcelain=v1 --untracked-files=no).Count -ne 0){throw 'REFUSE_DIRTY_TRACKED_FILES'}
$s=Get-Content -LiteralPath (Join-Path $data 'state.json') -Raw|ConvertFrom-Json
$c=Get-Content -LiteralPath (Join-Path $data 'supervisor-watchdog.json') -Raw|ConvertFrom-Json
$h=Get-Content -LiteralPath (Join-Path $data 'projects-live-control-plane-cutover-r42.json') -Raw|ConvertFrom-Json
if($s.settings.paused -ne $true -or $c.allowAutonomousSend -ne $false -or $h.holdActive -ne $false){throw 'REFUSE_PRECONDITION_CHANGED'}
if(@($s.agentAssignments|Where-Object{$_.state -in @('queued','dispatching','running','awaiting_evidence','unknown')}).Count -ne 0){throw 'REFUSE_UNSETTLED_ASSIGNMENTS'}
$life=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/operator-lifecycle' -TimeoutSec 12
if($life.mode -ne 'RUNNING_ATTACH'){throw 'REFUSE_OPERATOR_MODE_CHANGED'}
New-Item -ItemType Directory -Path $backup -ErrorAction Stop|Out-Null
$manifest=[ordered]@{contract='bridge.r65.private_safety_backup.v1';timestampUtc=[DateTime]::UtcNow.ToString('o');productionHead=$head.Trim();backupPath=$backup;files=@()}
foreach($name in @('state.json','supervisor-watchdog.json','projects-live-control-plane-cutover-r42.json')){
 $src=Join-Path $data $name; $dst=Join-Path $backup $name
 $before=(Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash
 Copy-Item -LiteralPath $src -Destination $dst -ErrorAction Stop
 $copied=(Get-FileHash -LiteralPath $dst -Algorithm SHA256).Hash
 $after=(Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash
 if($before -ne $copied -or $before -ne $after){throw ('BACKUP_SOURCE_CHANGED_DURING_COPY '+$name)}
 $manifest.files+=@{name=$name;sha256=$copied}
}
$manifest.serverSha256=(Get-FileHash -LiteralPath (Join-Path $app 'server.js') -Algorithm SHA256).Hash
$manifest|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $backup 'BACKUP_MANIFEST.json') -Encoding UTF8
Write-Output ('BACKUP_VERIFIED=True')
Write-Output ('FILE_COUNT='+$manifest.files.Count)
Write-Output ('BACKUP_ROOT='+$backup)
Write-Output ('PRODUCTION_HEAD='+$head.Trim())
Write-Output ('SERVER_SHA256='+$manifest.serverSha256)
Write-Output 'BACKUP_NOT_COMMITTED_TO_GIT=True'
